cd /tmp/sv-2ca9a3b04ad8443ea5355acc58521492/moderate-msbuild-properties && python3 -c "
import json
with open('after-cpm-packages.json') as f: after = json.load(f)
for p in after['projects']:
    name = p['path'].split('/')[-1]
    for fw in p['frameworks']:
        for pkg in fw['topLevelPackages']:
            print(f'{name}: {pkg[\"id\"]} {pkg[\"resolvedVersion\"]}')
"

